do $store$ declare n bigint; begin
	execute 'select count(*)::int as n from "employee_contract" a join "employee_contract" b on (a."id") < (b."id") and a."employee_id" is not distinct from b."employee_id" and a."effective_range" && b."effective_range" and (coalesce(a."status" = ''SEALED''::text, false)) and (coalesce(b."status" = ''SEALED''::text, false))' into n;
	if n > 0 then raise exception 'employee_contract__ex__89af20f6 refuses % existing row(s)', n; end if;
end $store$;
alter table "employee_contract" add constraint "employee_contract__ex__89af20f6" exclude using gist ("employee_id" with =, "effective_range" with &&) where (coalesce("status" = 'SEALED'::text, false)) deferrable initially immediate;
